package com.vandorlabs.neoforge.ramp;

import java.util.*;
import net.minecraft.core.BlockPos;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.phys.*;

/** Bounded physical-transfer metadata. Never contains entity NBT, stacks or credential ownership. */
public record NativeRampActorIntent(UUID operation,String dimension,BlockPos root,List<Participant> participants) {
 public static final int MAX_ACTORS=8192,MAX_BYTES=4*1024*1024;
 private static final Set<String> HEADER=Set.of("Schema","Operation","Dimension","Root","Actors");
 private static final Set<String> ACTOR=Set.of("Id","Type","From","To","Body","Velocity","Fall","Ground","NoPhysics","Impulse","HurtMarked");
 public record Participant(UUID id,String type,Vec3 from,Vec3 to,AABB body,Vec3 velocity,float fall,boolean ground,boolean noPhysics,boolean impulse,boolean hurtMarked) {
  public Participant {Objects.requireNonNull(id);resource(type);vector(from);vector(to);vector(velocity);Objects.requireNonNull(body);for(double value:new double[]{body.minX,body.minY,body.minZ,body.maxX,body.maxY,body.maxZ})finite(value);if(body.getXsize()<=0||body.getYsize()<=0||body.getZsize()<=0||body.getXsize()>64||body.getYsize()>64||body.getZsize()>64||!Float.isFinite(fall)||fall<0||fall>1e9)throw new IllegalArgumentException("Ramp actor physical bounds");}
 }
 public NativeRampActorIntent {Objects.requireNonNull(operation);resource(dimension);root=Objects.requireNonNull(root).immutable();var ordered=new ArrayList<>(participants);ordered.sort(Comparator.comparing(Participant::id));participants=List.copyOf(ordered);if(participants.isEmpty()||participants.size()>MAX_ACTORS)throw new IllegalArgumentException("Ramp actor count");var ids=new HashSet<UUID>();long bytes=1024;for(var actor:participants){if(!ids.add(actor.id()))throw new IllegalArgumentException("Duplicate Ramp actor");for(var point:List.of(actor.from(),actor.to(),new Vec3(actor.body().minX,actor.body().minY,actor.body().minZ),new Vec3(actor.body().maxX,actor.body().maxY,actor.body().maxZ)))if(Math.abs(point.x-root.getX())>128||Math.abs(point.y-root.getY())>128||Math.abs(point.z-root.getZ())>128)throw new IllegalArgumentException("Ramp actor outside operation bounds");bytes+=384+2L*actor.type().length();}if(bytes>MAX_BYTES)throw new IllegalArgumentException("Ramp actor retained budget");}
 public long retainedBytes(){long bytes=1024;for(var actor:participants)bytes+=384+2L*actor.type().length();return bytes;}
 public CompoundTag write(){var tag=new CompoundTag();tag.putInt("Schema",1);tag.putUUID("Operation",operation);tag.putString("Dimension",dimension);tag.putIntArray("Root",new int[]{root.getX(),root.getY(),root.getZ()});var list=new ListTag();for(var actor:participants){var row=new CompoundTag();row.putUUID("Id",actor.id());row.putString("Type",actor.type());row.put("From",numbers(actor.from().x,actor.from().y,actor.from().z));row.put("To",numbers(actor.to().x,actor.to().y,actor.to().z));row.put("Body",numbers(actor.body().minX,actor.body().minY,actor.body().minZ,actor.body().maxX,actor.body().maxY,actor.body().maxZ));row.put("Velocity",numbers(actor.velocity().x,actor.velocity().y,actor.velocity().z));row.putFloat("Fall",actor.fall());row.putBoolean("Ground",actor.ground());row.putBoolean("NoPhysics",actor.noPhysics());row.putBoolean("Impulse",actor.impulse());row.putBoolean("HurtMarked",actor.hurtMarked());list.add(row);}tag.put("Actors",list);if(tag.sizeInBytes()>MAX_BYTES)throw new IllegalArgumentException("Ramp actor encoded budget");return tag;}
 public static NativeRampActorIntent read(CompoundTag tag,UUID operation,String dimension,BlockPos root){keys(tag,HEADER);typed(tag,"Schema",Tag.TAG_INT);typed(tag,"Dimension",Tag.TAG_STRING);typed(tag,"Root",Tag.TAG_INT_ARRAY);typed(tag,"Actors",Tag.TAG_LIST);var coordinates=tag.getIntArray("Root");if(tag.getInt("Schema")!=1||!tag.hasUUID("Operation")||!operation.equals(tag.getUUID("Operation"))||!dimension.equals(tag.getString("Dimension"))||coordinates.length!=3||coordinates[0]!=root.getX()||coordinates[1]!=root.getY()||coordinates[2]!=root.getZ()||tag.sizeInBytes()>MAX_BYTES)throw new IllegalArgumentException("Ramp actor intent identity/schema");var list=tag.getList("Actors",Tag.TAG_COMPOUND);if(list.size()!=((ListTag)tag.get("Actors")).size()||list.isEmpty()||list.size()>MAX_ACTORS)throw new IllegalArgumentException("Ramp actor list");var rows=new ArrayList<Participant>(list.size());for(var element:list){var row=(CompoundTag)element;keys(row,ACTOR);if(!row.hasUUID("Id"))throw new IllegalArgumentException("Ramp actor UUID");typed(row,"Type",Tag.TAG_STRING);typed(row,"Fall",Tag.TAG_FLOAT);var from=values(row,"From",3);var to=values(row,"To",3);var body=values(row,"Body",6);if(body[3]<=body[0]||body[4]<=body[1]||body[5]<=body[2])throw new IllegalArgumentException("Ramp actor reversed body");var velocity=values(row,"Velocity",3);rows.add(new Participant(row.getUUID("Id"),row.getString("Type"),new Vec3(from[0],from[1],from[2]),new Vec3(to[0],to[1],to[2]),new AABB(body[0],body[1],body[2],body[3],body[4],body[5]),new Vec3(velocity[0],velocity[1],velocity[2]),row.getFloat("Fall"),flag(row,"Ground"),flag(row,"NoPhysics"),flag(row,"Impulse"),flag(row,"HurtMarked")));}return new NativeRampActorIntent(operation,dimension,root,rows);}
 private static void resource(String value){var parsed=value==null||value.length()>256?null:ResourceLocation.tryParse(value);if(parsed==null||!parsed.toString().equals(value))throw new IllegalArgumentException("Ramp actor resource identity");}
 private static void vector(Vec3 value){Objects.requireNonNull(value);finite(value.x);finite(value.y);finite(value.z);}
 private static void finite(double value){if(!Double.isFinite(value)||Math.abs(value)>30000128)throw new IllegalArgumentException("Ramp actor finite coordinate");}
 private static ListTag numbers(double... values){var list=new ListTag();for(double value:values)list.add(DoubleTag.valueOf(value));return list;}
 private static double[] values(CompoundTag tag,String key,int count){typed(tag,key,Tag.TAG_LIST);var list=tag.getList(key,Tag.TAG_DOUBLE);if(list.size()!=count||((ListTag)tag.get(key)).size()!=count)throw new IllegalArgumentException("Ramp actor vector shape");var values=new double[count];for(int i=0;i<count;i++)values[i]=list.getDouble(i);return values;}
 private static boolean flag(CompoundTag tag,String key){typed(tag,key,Tag.TAG_BYTE);byte value=tag.getByte(key);if(value!=0&&value!=1)throw new IllegalArgumentException("Ramp actor flag");return value==1;}
 private static void keys(CompoundTag tag,Set<String> keys){if(!tag.getAllKeys().equals(keys))throw new IllegalArgumentException("Unknown Ramp actor fields");}
 private static void typed(CompoundTag tag,String key,int type){if(!tag.contains(key,type))throw new IllegalArgumentException("Ramp actor field type "+key);}
}
